from llguidance.gbnf_to_lark import (
    ASTNode, AlternativeNode, GrammarParser, LiteralNode, RegexNode,
    RepetitionNode, RuleNode, RuleRefNode, SequenceNode, resolve
)
from pathlib import Path

text = Path('resources/ground_truth/json_ws.gbnf').read_text()
parser = GrammarParser()
rules = parser.parse(text)
resolve(rules)

for name, rule in sorted(rules.items()):
    print(f'{name}: terminal={rule.rule_is_terminal}, order={rule.order}')
    body = rule.alternatives
    print(f'  body type: {type(body).__name__}')
    if hasattr(body, 'alternatives'):
        for a in body.alternatives:
            print(f'    alt: {type(a).__name__}', end='')
            if hasattr(a, 'name'): print(f' name={a.name}', end='')
            if hasattr(a, 'value'): print(f' value={a.value!r}', end='')
            print()
    elif hasattr(body, 'nodes'):
        for n in body.nodes:
            print(f'    seq: {type(n).__name__}', end='')
            if hasattr(n, 'name'): print(f' name={n.name}', end='')
            if hasattr(n, 'value'): print(f' value={n.value!r}', end='')
            print()
